<template>
  <div class="w-full flex items-center justify-between">
    <div class="flex items-center gap-2">
      <h3 class="text-base font-semibold">{{ title }}</h3>
      <slot />
    </div>
    <div class="flex items-center gap-2">
      <NuxtLink v-if="editTo" :to="editTo">
        <Button variant="outline" :prepend-icon="PencilIcon">Edit</Button>
      </NuxtLink>
      <ConfirmationDialog2
        v-if="isRemovable"
        v-model:model-value="open"
        :title="confirmTitle ?? `Are you sure you want to remove ${title} data for this canvasser?`"
        :description="
          confirmDescription ?? 'This action cannot be undone. User will be forced to fill this information again.'
        "
        :confirm-btn-variant="confirmBtnVariant"
        :confirm-btn-text="actionTitle"
        is-awaited-close
        :confirm="onActionClick"
        :is-confirm-loading="pending"
      >
        <Button variant="outline" :prepend-icon="actionIcon">{{ actionTitle }}</Button>
      </ConfirmationDialog2>
    </div>
  </div>
</template>

<script setup lang="ts">
import { PencilIcon, Trash, type LucideIcon } from 'lucide-vue-next';
import type { RouteLocationRaw } from 'vue-router';

interface Props {
  title: string;
  isRemovable?: boolean;
  actionFunction?: () => Promise<void>;
  actionTitle?: string;
  actionIcon?: LucideIcon;
  confirmTitle?: string;
  confirmDescription?: string;
  confirmBtnVariant?: 'destructive' | 'default';
  pending?: boolean;
  // When set, renders an "Edit" link button alongside the header (e.g. general info).
  editTo?: RouteLocationRaw;
}

const props = withDefaults(defineProps<Props>(), {
  isRemovable: false,
  actionFunction: undefined,
  actionTitle: 'Clear',
  actionIcon: () => Trash,
  confirmTitle: undefined,
  confirmDescription: undefined,
  confirmBtnVariant: 'destructive',
  pending: false,
  editTo: undefined,
});

const open = ref<boolean>(false);

async function onActionClick() {
  if (props.actionFunction)
    await props.actionFunction().then(() => {
      open.value = false;
    });
}
</script>

<style scoped lang="scss"></style>
