<template>
  <Card>
    <CardHeader>
      <CardTitle>{{ cardTitle }}</CardTitle>
    </CardHeader>
    <CardContent class="flex flex-col gap-4">
      <template v-if="isCanvasserDetails">
        <UserDetailsCanvasserInfoHeader
          title="General Information"
          :is-removable="Boolean(canvasserGeneralInfo)"
          :action-function="async () => await onRemoveCanvasserInfo('general_info')"
          :pending="isRemovingCanvasserInfo"
          :edit-to="
            isAdmin && canvasserGeneralInfo
              ? { name: 'users-id-edit-general-info', params: { id: userDetails.id } }
              : undefined
          "
        />
        <div v-if="canvasserGeneralInfo" class="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <LabeledValue v-for="(item, index) in generalInfo" :key="index" :label="item.title">
            <template v-if="item.title === 'Equipment Confirmation'">
              <Check
                v-if="canvasserGeneralInfo.equipment_confirmation"
                class="min-w-5 max-w-5 h-5 stroke-green-600 inline"
              />
              <X v-else class="min-w-5 max-w-5 h-5 stroke-red-600 inline" />
            </template>
            {{ item.value }}
          </LabeledValue>
        </div>
        <div v-else class="text-muted-foreground">Canvasser did not provide general information yet</div>
        <EntityAuditInfo :audit="userDetails.canvasser_general_info_audit" />
        <Separator />
        <UserDetailsCanvasserInfoHeader
          title="Identification Documents"
          :is-removable="Boolean(canvasserDocumentsInfo)"
          :action-function="async () => await onRemoveCanvasserInfo('documents')"
          :pending="isRemovingCanvasserInfo"
        />
        <div
          v-if="canvasserDocumentsInfo?.documents.length"
          class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4"
        >
          <template v-for="item in canvasserDocumentsInfo.documents" :key="item.id">
            <ImagePreviewDialog
              :src="item.s3_url"
              alt="Identification document"
              title="Identification document"
              description="Enlarged identification document preview."
            >
              <template #trigger>
                <img class="h-full w-full cursor-pointer object-contain" :src="item.s3_url" />
              </template>
            </ImagePreviewDialog>
          </template>
        </div>
        <div v-else class="text-muted-foreground">Canvasser did not provide documents yet</div>
        <Separator />
        <UserDetailsCanvasserInfoHeader
          title="W-9 Form"
          :is-removable="w9Status !== 'pending'"
          :action-title="hasW9Data ? 'Clear' : 'Send Form'"
          :action-icon="hasW9Data ? Trash : Send"
          :action-function="onSendOrResendW9Form"
          :confirm-title="
            hasW9Data
              ? 'Are you sure you want to remove W-9 Form data for this canvasser?'
              : 'Are you sure you want to resend the W-9 form?'
          "
          confirm-description="This action clears the canvasser's data for this block and immediately sends a new W-9 signing request."
          :confirm-btn-variant="hasW9Data ? 'destructive' : 'default'"
          :pending="isSendOrResendingW9Form"
        >
          <Badge :variant="w9StatusEntry.variant" size="sm">{{ w9StatusEntry.label }}</Badge>
        </UserDetailsCanvasserInfoHeader>
        <div class="grid grid-cols-1 gap-4">
          <div
            v-if="canvasserW9FormInfo?.contract_id || canvasserW9FormInfo?.ssn"
            class="grid grid-cols-1 sm:grid-cols-2 gap-4"
          >
            <LabeledEntityContract
              v-if="canvasserW9FormInfo?.contract_id"
              :contract-id="canvasserW9FormInfo.contract_id"
            />
            <LabeledValue v-if="canvasserW9FormInfo?.ssn" label="Social Security Number">
              {{ canvasserW9FormInfo.ssn }}
            </LabeledValue>
          </div>
          <NuxtLink
            v-if="canvasserW9FormInfo?.w9_completed_url"
            :to="canvasserW9FormInfo.w9_completed_url"
            target="_blank"
            rel="noopener noreferrer"
          >
            <Button variant="outline" :prepend-icon="LinkIcon">Open Completed W-9 Form</Button>
          </NuxtLink>
          <p v-if="w9Status === 'not_sent'" class="text-muted-foreground">W-9 form has not been sent yet</p>
        </div>
        <Separator />
      </template>
      <UserDetailsCanvasserInfoHeader
        title="Verification Sample"
        :is-removable="Boolean(canvasserVoiceSampleInfo)"
        :action-function="async () => await onRemoveCanvasserInfo('voice_sample')"
        :pending="isRemovingCanvasserInfo"
      />
      <AccountAudioPlayer v-if="canvasserVoiceSampleInfo" :url="canvasserVoiceSampleInfo.url">
        <p v-if="canvasserVoiceSampleInfo?.updated_at" class="text-accent-foreground leading-7">
          Last updated: {{ formatDateTzToFormat(canvasserVoiceSampleInfo.updated_at, 'MM/dd/yyyy HH:mm', timezone) }}
        </p>
      </AccountAudioPlayer>
      <div v-else class="text-muted-foreground">{{ subjectNoun }} did not provide a sample yet</div>
      <template v-if="isCanvasserDetails">
        <Separator />
        <UserDetailsCanvasserInfoHeader title="Payment Information" :pending="isRemovingCanvasserInfo" />
        <template v-if="canvasserPaymentInfo">
          <LabeledValue label="Eligible For Same Day Payout" class="!flex-row items-center">
            <Check
              v-if="canvasserPaymentInfo.eligible_for_same_day_payout"
              class="min-w-5 max-w-5 h-5 stroke-green-600 inline"
            />
            <X v-else class="min-w-5 max-w-5 h-5 stroke-red-600 inline" />
          </LabeledValue>
          <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div class="flex gap-2 items-center">
              <Label for="same_day_payout" class="text-accent-foreground">Same Day Payout</Label>
              <Switch
                id="same_day_payout"
                v-model="canvasserPaymentInfo.same_day_payout_enabled"
                @update:model-value="async (value) => await onTogglePaymentInfo('same_day_payout_enabled', value)"
              >
                <template #thumb>
                  <Spinner
                    v-if="isUpdateUserPaymentInfoLoading && paymentInfoFieldChanges === 'same_day_payout_enabled'"
                    class="w-5 h-5 fill-foreground"
                  />
                </template>
              </Switch>
            </div>
            <div class="flex gap-2 items-center">
              <Label for="weekly_payroll" class="text-accent-foreground">Weekly Payroll</Label>
              <Switch
                id="weekly_payroll"
                v-model="canvasserPaymentInfo.weekly_payroll_enabled"
                @update:model-value="async (value) => await onTogglePaymentInfo('weekly_payroll_enabled', value)"
              >
                <template #thumb>
                  <Spinner
                    v-if="isUpdateUserPaymentInfoLoading && paymentInfoFieldChanges === 'weekly_payroll_enabled'"
                    class="w-5 h-5 fill-foreground"
                  />
                </template>
              </Switch>
            </div>
          </div>
          <EarningsBranchStatusContent :status="canvasserPaymentInfo.account_status" />
        </template>
        <div v-else class="text-muted-foreground">Canvasser did not finish onboarding process</div>
      </template>
      <template v-if="isCanvasserDetails">
        <Separator />
        <UserDetailsCanvasserInfoHeader title="Registered Party" />
        <div class="flex gap-2">
          <LabeledSelect
            v-model="selectedParty"
            :items="parties"
            class="max-w-[200px]"
            data-testid="canvasser-info-registered-party-select"
          />
          <Button
            class="h-10"
            data-testid="canvasser-info-registered-party-save"
            :disabled="!hasPartyChanges || isEditingRegisteredParty"
            :loading="isEditingRegisteredParty"
            @click="
              editUserRegisteredParty({
                userId: userDetails.id,
                registeredParty: selectedParty.value,
              })
            "
          >
            Save Changes
          </Button>
        </div>
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { Check, LinkIcon, Send, Trash, X } from 'lucide-vue-next';
import type { GetUserDetailsResponse, MilitaryService, CanvasserSection, RegisteredParty } from '~/client';
import { useRemoveCanvasserInto } from '~/mutations/users/removeCanvasserInfo';
import { useSendOrResendW9Form } from '~/mutations/users/sendOrResendW9Form';
import { useUpdateUserPaymentInfo } from '~/mutations/users/updatePaymentInfo';
import { getUiContractSigningStatus } from '~/constants/contracts/uiContractSigningStatusConfig';
import { Spinner } from '~/assets/icons';
import { registeredParties, getRegisteredParty } from '~/constants/users/registeredParties';
import { useEditRegisteredParty } from '~/mutations/users/editRegisteredParty';

type ValueOf<T> = T[keyof T];

interface CanvasserInfoItem {
  title: string;
  value?: ValueOf<GetUserDetailsResponse>;
}

const props = defineProps({
  userDetails: {
    type: Object as PropType<GetUserDetailsResponse>,
    required: true,
  },
});

const { timezone, isAdmin } = useUserRole();

// Subcontractor canvassers only provide a voice sample and profile information, so the
// remaining application sections (general info, documents, W-9 form, payment) are shown
// for regular canvassers only.
const isCanvasserDetails = computed(() => props.userDetails?.role === 'canvasser');

// The voice sample and profile sections also render for subcontractor canvassers, so the
// card title and their empty states use the role-appropriate noun instead of always "Canvasser".
const cardTitle = computed(() =>
  isCanvasserDetails.value ? 'Canvasser Application' : 'Subcontractor Canvasser Application'
);
const subjectNoun = computed(() => (isCanvasserDetails.value ? 'Canvasser' : 'Subcontractor canvasser'));

const canvasserGeneralInfo = computed(() => props.userDetails?.canvasser_general_info);
const canvasserDocumentsInfo = computed(() => props.userDetails?.canvasser_documents);
const canvasserVoiceSampleInfo = computed(() => props.userDetails?.canvasser_voice_sample);
const canvasserPaymentInfo = computed(() => props.userDetails?.canvasser_payment_info);
const canvasserW9FormInfo = computed(() => props.userDetails?.canvasser_w9_form_info);
const w9Status = computed(() => canvasserW9FormInfo.value?.status ?? 'not_sent');
const w9StatusEntry = computed(() => getUiContractSigningStatus(w9Status.value));
const hasW9Data = computed(() => w9Status.value !== 'not_sent');

const militaryServices: Record<MilitaryService, string> = {
  military_family: 'Military Family',
  military_spouse: 'Military Spouse',
  veteran: 'Veteran',
  na: 'N/a',
};

const generalInfo = computed<CanvasserInfoItem[]>(() => [
  {
    title: 'Address',
    value: canvasserGeneralInfo.value?.address,
  },
  {
    title: 'City',
    value: canvasserGeneralInfo.value?.city,
  },
  {
    title: 'State',
    value: canvasserGeneralInfo.value?.state,
  },
  {
    title: 'Zip',
    value: canvasserGeneralInfo.value?.zip_code,
  },
  {
    title: 'Date of Birth',
    value: canvasserGeneralInfo.value?.date_of_birth
      ? formatUTCDateString(canvasserGeneralInfo.value.date_of_birth, 'MM/dd/yyyy')
      : undefined,
  },
  {
    title: 'Military Service',
    value: canvasserGeneralInfo.value?.military_service
      ? militaryServices[canvasserGeneralInfo.value.military_service]
      : '',
  },
  {
    title: 'Equipment Confirmation',
    value: canvasserGeneralInfo.value?.equipment_confirmation
      ? 'Has smartphone and ability to drive'
      : 'Has no required equipment',
  },
  {
    title: 'Referral Source',
    value: canvasserGeneralInfo.value?.referral_source,
  },
]);

const { removeCanvasserInfo, isRemovingCanvasserInfo } = useRemoveCanvasserInto();

async function onRemoveCanvasserInfo(section: CanvasserSection) {
  await removeCanvasserInfo({
    userId: props.userDetails.id,
    section: section,
  });
}

const { sendOrResendW9Form, isSendOrResendingW9Form } = useSendOrResendW9Form();

async function onSendOrResendW9Form() {
  await sendOrResendW9Form({
    userId: props.userDetails.id,
  });
}

const paymentInfoFieldChanges = ref<string | null>(null);
const { updateUserPaymentInfo, isUpdateUserPaymentInfoLoading } = useUpdateUserPaymentInfo();

async function onTogglePaymentInfo(field: 'same_day_payout_enabled' | 'weekly_payroll_enabled', value: boolean) {
  paymentInfoFieldChanges.value = field;
  try {
    await updateUserPaymentInfo({
      userId: props.userDetails.id,
      body: {
        [field]: value,
      },
    });
  } catch (err) {
    console.log('Failed to update payment status', err);
  } finally {
    paymentInfoFieldChanges.value = null;
  }
}

const selectedParty = ref<{ name: string; value: RegisteredParty }>({
  name: getRegisteredParty(props.userDetails.registered_party).name,
  value: props.userDetails.registered_party,
});

const parties = computed<SelectItem[]>(() => [
  ...Object.entries(registeredParties).map(([key, { name }]) => ({
    name,
    value: key,
  })),
]);

const hasPartyChanges = computed(() => {
  return selectedParty.value?.value !== props.userDetails.registered_party;
});

const { editUserRegisteredParty, isEditingRegisteredParty } = useEditRegisteredParty();
</script>

<style scoped lang="scss"></style>
