import { editUserRegisteredParty } from '~/client';
import type { RegisteredParty, UserDetailsResponse, UserRegisteredPartyEditResponse } from '~/client';

export const useEditRegisteredParty = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: { userId: string; registeredParty: RegisteredParty }): Promise<UserRegisteredPartyEditResponse> =>
      editUserRegisteredParty({
        composable: '$fetch',
        path: { user_id: data.userId },
        body: { registered_party: data.registeredParty },
      }),
    onSuccess: (newData, data) => {
      queryCache.setQueryData(['user', data.userId], (oldData?: UserDetailsResponse) => {
        if (!oldData) return oldData;
        const key = `registered_party` as keyof UserDetailsResponse;
        return {
          ...oldData,
          [key]: data.registeredParty,
        };
      });
      showToastSuccess('Registered party updated successfully');
    },
    onError: (err) => {
      showToastError(err.message);
    },
  });

  return {
    editUserRegisteredParty: mutateAsync,
    isEditingRegisteredParty: computed(() => asyncStatus.value === 'loading'),
  };
});
