import { requestCheckrBackgroundCheck } from '~/client';

export const useRequestCheckrBackgroundCheck = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: requestCheck, asyncStatus } = useMutation({
    mutation: (user_id: string) => requestCheckrBackgroundCheck({ composable: '$fetch', path: { user_id } }),
    onSuccess: (_, user_id) => {
      queryCache.invalidateQueries({ key: ['user', user_id] });
      showToastSuccess('Background check requested successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    requestCheck,
    isRequestingCheck: computed(() => asyncStatus.value === 'loading'),
  };
});
