<template>
  <ConfirmationDialog
    title="Confirm action"
    :description="value ? changeToFalseConfirmation : changeToTrueConfirmation"
    confirm-btn-variant="default"
    confirm-btn-text="Confirm"
    :is-confirm-loading="isUserHiringCheckmarkEditLoading"
    @confirm="() => onUserHiringCheckmarkEdit(!value)"
  >
    <Button
      class="justify-start px-2"
      :class="[
        {
          'text-red-600': value && isError,
          'border-red-600': value && isCritical,
          'border-green-600': value && !isError,
        },
        $attrs.class,
      ]"
      variant="outline"
      size="lg"
    >
      <Check v-if="value" class="inline mr-2" :class="isError ? 'stroke-red-600' : 'stroke-green-600'" />
      <XIcon v-else class="stroke-muted-foreground inline mr-2" />
      {{ label }}
    </Button>
  </ConfirmationDialog>
</template>
<script setup lang="ts">
import { Check, XIcon } from 'lucide-vue-next';
import { useUserHiringCheckmarkEdit } from '~/mutations/users/hiring/edit';
import type { HiringCheckmark } from '~/client';

const props = defineProps({
  label: {
    type: String,
    required: true,
  },
  value: {
    type: Boolean,
    required: true,
  },
  isSystem: {
    type: Boolean,
    default: false,
  },
  variant: {
    type: String as PropType<'default' | 'error' | 'critical'>,
    default: 'default',
  },
  changeToTrueConfirmation: {
    type: String,
    required: true,
  },
  changeToFalseConfirmation: {
    type: String,
    required: true,
  },
  userId: {
    type: String,
    required: true,
  },
  checkmarkId: {
    type: String as PropType<HiringCheckmark>,
    required: true,
  },
});

const isError = computed(() => props.variant === 'error' || props.variant === 'critical');
const isCritical = computed(() => props.variant === 'critical');
const { userHiringCheckmarkEdit, isUserHiringCheckmarkEditLoading } = useUserHiringCheckmarkEdit();

async function onUserHiringCheckmarkEdit(value: boolean) {
  await userHiringCheckmarkEdit({ user_id: props.userId, checkmark: props.checkmarkId, value });
}
</script>
