<template>
  <Card>
    <CardHeader class="flex flex-row flex-wrap gap-4 justify-between items-center">
      <CardTitle>Checkr Status</CardTitle>
      <UserDetailsCheckrStatus :status="data.status" />
    </CardHeader>
    <CardContent class="flex flex-col gap-2">
      <Alert :variant="details.variant as AlertVariants['variant']">
        <component :is="details.icon" />
        <AlertTitle>{{ details.title }}</AlertTitle>
        <AlertDescription>{{ details.description }}</AlertDescription>
        <div v-if="data.invitation_expires_at" class="mt-3 flex flex-wrap gap-2">
          <CheckrInvitationExpiry
            :expires-at="data.invitation_expires_at"
            :expired="data.status === 'invitation_expired'"
          />
        </div>
      </Alert>
      <template v-if="data.details_url || (data.error && data.error.length)">
        <NuxtLink v-if="data.details_url" :to="data.details_url" target="_blank" rel="noopener noreferrer">
          <Button variant="outline" :prepend-icon="LinkIcon">Open Details on Portal</Button>
        </NuxtLink>
        <div v-if="data.error && data.error.length">
          <p>Checkr request errors:</p>
          <div class="flex flex-col text-wrap mt-1">
            <p v-for="(error, index) in data.error" :key="index" class="text-destructive">
              <span class="text-card-foreground">&middot;</span> {{ error }}
            </p>
          </div>
        </div>
      </template>
      <TooltipProvider :disabled="!isInFlight">
        <Tooltip>
          <TooltipTrigger as-child>
            <span>
              <Button
                variant="outline"
                :prepend-icon="RefreshCwIcon"
                :disabled="isInFlight || isRequestingCheck"
                :loading="isRequestingCheck"
                @click="onRequestCheck"
              >
                Request Background Check
              </Button>
            </span>
          </TooltipTrigger>
          <TooltipContent>A background check is already in progress.</TooltipContent>
        </Tooltip>
      </TooltipProvider>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { UserDetailsCheckrBackgroundCheck } from '~/client';
import { LinkIcon, RefreshCwIcon } from 'lucide-vue-next';
import type { AlertVariants } from '~/components/ui/alert';
import { getUserCheckerStatus, checkrInFlightStatuses } from '~/constants/users/checkerStatuses';
import UserDetailsCheckrStatus from '~/components/users/details/UserDetailsCheckrStatus.vue';
import { useRequestCheckrBackgroundCheck } from '~/mutations/users';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '~/components/ui/tooltip';

interface Props {
  userId: string;
  data: UserDetailsCheckrBackgroundCheck;
}

const props = defineProps<Props>();

const details = computed(() => getUserCheckerStatus(props.data.status));
const isInFlight = computed(() => checkrInFlightStatuses.includes(props.data.status));

const { requestCheck, isRequestingCheck } = useRequestCheckrBackgroundCheck();

const onRequestCheck = async () => {
  await requestCheck(props.userId);
};
</script>
