import {
  editUserHiringCheckmark,
  type UserHiringCheckmarkEditRequest,
  type UserHiringCheckmarkEditResponse,
} from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useUserHiringCheckmarkEdit = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: UserHiringCheckmarkEditRequest): Promise<UserHiringCheckmarkEditResponse> =>
      editUserHiringCheckmark({
        composable: '$fetch',
        body: vars,
      }),
    onSuccess: async (newData, { user_id }) => {
      showToastSuccess('Hiring status updated successfully');
      await queryCache.invalidateQueries({ key: ['user', user_id], exact: true });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    userHiringCheckmarkEdit: mutateAsync,
    isUserHiringCheckmarkEditLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
