import { editPaymentUserSettings } from '~/client';
import type { EditPaymentUserSettingsRequest, EditPaymentUserSettingsResponse, GetUserDetailsResponse } from '~/client';

export const useUpdateUserPaymentInfo = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: {
      userId: string;
      body: EditPaymentUserSettingsRequest;
    }): Promise<EditPaymentUserSettingsResponse> =>
      editPaymentUserSettings({
        composable: '$fetch',
        path: { user_id: data.userId },
        body: ref(data.body),
      }),
    onMutate: (data) => {
      const userData: GetUserDetailsResponse | undefined = queryCache.getQueryData(['user', data.userId]);
      if (!userData) return;
      queryCache.setQueryData(['user', data.userId], () => {
        return {
          ...userData,
          canvasser_payment_info: {
            ...userData.canvasser_payment_info,
            ...data.body,
          },
        };
      });
    },
    onSuccess: async (_, data) => {
      showToastSuccess(`Payment info updated successfully`);
      const userData: GetUserDetailsResponse | undefined = queryCache.getQueryData(['user', data.userId]);
      if (!userData) return;
      queryCache.setQueryData(['user', data.userId], () => {
        const weeklyPayroll =
          'weekly_payroll_enabled' in data.body
            ? data.body.weekly_payroll_enabled
            : userData.canvasser_payment_info?.weekly_payroll_enabled;
        const sameDayPayout =
          'same_day_payout_enabled' in data.body
            ? data.body.same_day_payout_enabled
            : userData.canvasser_payment_info?.same_day_payout_enabled;
        return {
          ...userData,
          canvasser_payment_info: {
            ...userData.canvasser_payment_info,
            ...data.body,
            same_day_payout_enabled: weeklyPayroll ? sameDayPayout : false,
          },
        };
      });
    },
    onError(error, data) {
      showToastError(error);
      const userData: GetUserDetailsResponse | undefined = queryCache.getQueryData(['user', data.userId]);
      if (!userData) return;
      queryCache.setQueryData(['user', data.userId], () => {
        const weeklyPayroll =
          'weekly_payroll_enabled' in data.body
            ? !data.body.weekly_payroll_enabled
            : userData.canvasser_payment_info?.weekly_payroll_enabled;
        return {
          ...userData,
          canvasser_payment_info: {
            ...userData?.canvasser_payment_info,
            same_day_payout_enabled: !weeklyPayroll
              ? false
              : 'same_day_payout_enabled' in data.body
                ? !data.body.same_day_payout_enabled
                : userData.canvasser_payment_info?.same_day_payout_enabled,
            weekly_payroll_enabled: weeklyPayroll,
          },
        };
      });
    },
  });

  return {
    updateUserPaymentInfo: mutateAsync,
    isUpdateUserPaymentInfoLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
