import { sendOrResendW9Form } from '~/client';
import type { SendOrResendW9FormResponse, UserDetailsResponse } from '~/client';

export const useSendOrResendW9Form = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: { userId: string }): Promise<SendOrResendW9FormResponse> =>
      sendOrResendW9Form({
        composable: '$fetch',
        body: { canvasser_id: data.userId },
      }),
    onSuccess: (_, data) => {
      queryCache.setQueryData(['user', data.userId], (oldData?: UserDetailsResponse) => {
        if (!oldData) return oldData;
        return {
          ...oldData,
          canvasser_w9_form_info: {
            contract_id: null,
            ssn: null,
            status: 'pending' as const,
            w9_completed_url: null,
          },
        };
      });
      showToastSuccess('W-9 form sent successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    sendOrResendW9Form: mutateAsync,
    isSendOrResendingW9Form: computed(() => asyncStatus.value === 'loading'),
  };
});
