<template>
  <Card>
    <CardHeader>
      <CardTitle>Hiring Information</CardTitle>
    </CardHeader>
    <CardContent>
      <div class="flex flex-col gap-4">
        <template v-if="fullChecks">
          <div class="grid grid-cols-1 gap-4">
            <UserHiringCheckmark
              :value="fullChecks.application_completed"
              label="Application completed"
              change-to-true-confirmation="Do you want to mark canvasser application as <b>completed</b> for this user?"
              change-to-false-confirmation="Do you want to mark canvasser application as <b>NOT completed</b> for this user? <br/><br/> This will force them to create application again"
              :is-system="true"
              :user-id="userId"
              checkmark-id="application_completed"
            />
          </div>
          <div class="grid grid-cols-1 gap-4">
            <UserHiringCheckmark
              :value="fullChecks.social_media_checked"
              label="Social media checked"
              change-to-true-confirmation="Do you want to mark social media check as <b>checked</b> for this user? <br/><br/> This indicates that the person is good to proceed with onboarding."
              change-to-false-confirmation="Do you want to mark social media check as <b>NOT checked</b> for this user? <br/><br/> This indicates that the person is not eligible to proceed with onboarding."
              :is-system="true"
              :user-id="userId"
              checkmark-id="social_media_checked"
            />
          </div>
          <Separator />
          <div class="grid grid-cols-1 gap-4">
            <UserHiringCheckmark
              :value="fullChecks.good_to_hire"
              label="Good to Hire"
              change-to-true-confirmation="Do you want to mark this user as <b>Good to Hire</b>? <br/><br/> This will notify HR to proceed with papers."
              change-to-false-confirmation="Do you want to mark this user as <b>NOT Good to Hire</b>? <br/><br/> This will prevent the user from proceeding with papers."
              :user-id="userId"
              checkmark-id="good_to_hire"
            />
          </div>
          <Separator />
        </template>
        <div class="grid grid-cols-1 gap-4">
          <UserHiringCheckmark
            :value="props.hiringChecks.do_not_hire"
            label="Do Not Hire"
            change-to-true-confirmation="Do you want to mark this user as <b>Do Not Hire</b>? <br/><br/> This will notify HR to never hire this user."
            change-to-false-confirmation="Do you want to <b>REMOVE</b> this user from the <b>Do Not Hire</b> list? <br/><br/> This will notify HR that the user could be hired."
            variant="critical"
            :user-id="userId"
            checkmark-id="do_not_hire"
          />
        </div>
        <div v-if="similarityStatus" class="flex flex-wrap items-center gap-2">
          <span>Similarity Check Status: </span>
          <Badge :variant="getUserSimilarityCheckStatus(similarityStatus).variant">{{
            getUserSimilarityCheckStatus(similarityStatus).label
          }}</Badge>
        </div>
      </div>
    </CardContent>
  </Card>
</template>
<script lang="ts" setup>
import type { PropType } from 'vue';
import type { HiringChecks, SubcontractorHiringChecks, UserSimilarityCheckStatus } from '~/client';
import { getUserSimilarityCheckStatus } from '~/constants/users/similarityCheckStatuses';

const props = defineProps({
  userId: {
    type: String,
    required: true,
  },
  hiringChecks: {
    type: Object as PropType<HiringChecks | SubcontractorHiringChecks>,
    required: true,
  },
  similarityStatus: {
    type: String as PropType<UserSimilarityCheckStatus>,
    required: false,
    default: undefined,
  },
});

// Subcontractor canvassers only have the `do_not_hire` check. The full set of
// checks (application, social media, good to hire) is exposed only for regular
// canvassers, so narrow on `application_completed` to render those conditionally.
const fullChecks = computed<HiringChecks | null>(() =>
  'application_completed' in props.hiringChecks ? props.hiringChecks : null
);
</script>
